var tokens = (Console.ReadLine() ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);
if (tokens.Length != 2) Environment.Exit(1);
ITransform? transform = tokens[0] switch
{
    "upper" => new UpperCaseTransform(),
    "lower" => new LowerCaseTransform(),
    "len" => new LengthTransform(),
    _ => null
};
if (transform is null) Environment.Exit(1);
Console.WriteLine(transform.Apply(tokens[1]));

interface ITransform
{
    string Apply(string text);
}

class UpperCaseTransform : ITransform
{
    public string Apply(string text) => text.ToUpperInvariant();
}

class LowerCaseTransform : ITransform
{
    public string Apply(string text) => text.ToLowerInvariant();
}

class LengthTransform : ITransform
{
    public string Apply(string text) => text.Length.ToString();
}
